        return node.id in ("id", "name", "email")
    if isinstance(node, ast.Compare):
        for op in node.ops:
            if not isinstance(op, (ast.Eq, ast.NotEq, ast.Lt, ast.LtE, ast.Gt, ast.GtE)):
                return False
        return _validate_node(node.left) and all(_validate_node(c) for c in node.comparators)
    if isinstance(node, ast.BoolOp):
        if not isinstance(node.op, (ast.And, ast.Or)):
            return False
        return all(_validate_node(v) for v in node.values)
    if isinstance(node, ast.UnaryOp):
        return isinstance(node.op, ast.Not) and _validate_node(node.operand)
    return False


def _evaluate_node(node, user):
    if isinstance(node, ast.Constant):
        return node.value
    if isinstance(node, ast.Name):
        return user[node.id]
    if isinstance(node, ast.Compare):
        left_val = _evaluate_node(node.left, user)
        res = True
        for i, op in enumerate(node.ops):
            right_val = _evaluate_node(node.comparators[i], user)

            if isinstance(op, ast.Eq):
                res = left_val == right_val
            elif isinstance(op, ast.NotEq):
                res = left_val != right_val
            elif isinstance(op, ast.Lt):
                res = left_val < right_val
            elif isinstance(op, ast.LtE):
                res = left_val <= right_val
            elif isinstance(op, ast.Gt):
                res = left_val > right_val
            elif isinstance(op, ast.GtE):
                res = left_val >= right_val
            else:
                raise ValueError("Unknown operator")

            if not res:
                return False
            left_val = right_val
        return True
    if isinstance(node, ast.BoolOp):
        values = [_evaluate_node(v, user) for v in node.values]
        if isinstance(node.op, ast.And):
            return all(values)
        if isinstance(node.op, ast.Or):
            return any(values)
    if isinstance(node, ast.UnaryOp):
        return not _evaluate_node(node.operand, user)
    raise ValueError("Unknown node")


def filter_users(where_expr: str) -> list[dict] | None:
    try:
        tree = ast.parse(where_expr, mode="eval")
        if not _validate_node(tree.body):
            return None

        users = store.get_all_users()
        matches = []
        for user in users:
            if _evaluate_node(tree.body, user):
                matches.append(user)
        return matches
    except SyntaxError:
        return None
